    private static Long keel(Person p, Long averageScaled) {
        Long momentum = momentum(p);
        Long norm = norm(p, averageScaled);
        return momentum == null || norm == null ? null : 2L * scaled(p) + 3L * momentum + 2L * norm + 2L * thrust(p);
